const stdout = $input.first().json.stdout;
const customerData = $('When called by Master').first().json;

const n8nAdminMatch = stdout.match(/Admin Password: (.+)/);
const customerPassMatch = stdout.match(/Customer Password: (.+)/);

const n8nAdminPassword = n8nAdminMatch ? n8nAdminMatch[1].trim() : null;
const customerPassword = customerPassMatch ? customerPassMatch[1].trim() : null;

if (!n8nAdminPassword || !customerPassword) {
  throw new Error('Failed to extract credentials from setup output');
}

return [{
  json: {
    server_ip: customerData.server.ip,
    domain: customerData.domain,
    n8n_admin_password: n8nAdminPassword,
    customer_password: customerPassword,
    postgresql_installed: true,
    authelia_installed: true
  }
}];

const customerData = $('When called by Master').first().json;
const credentials = $('Extract Credentials').first().json;
const startTime = new Date(customerData.deployment.started_at);
const duration = Math.round((new Date() - startTime) / 1000);

const crypto = require('crypto');
const n8nApiKey = crypto.randomBytes(32).toString('hex');

return [{
  json: {
    status: 'success',
    phase: 'server_setup',
    duration: duration,

    n8n_ready: true,
    n8n_url: `https://${credentials.domain}`,
    n8n_credentials: {
      admin_password: credentials.n8n_admin_password
    },
    n8n_api_key: n8nApiKey,

    authelia_url: `https://${credentials.domain}/authelia`,
    authelia_credentials: {
      customer_password: credentials.customer_password
    },

    postgresql_ready: true,

    message: 'Server setup complete with Docker, n8n, PostgreSQL, and Authelia'
  }
}];
